def get_hero_base_stats(ename, cname, role_str="战士"):
    """
    获取指定英雄的基础属性面板（包含1级基础、15级成长、物攻、物抗、魔抗、移速、自带攻速与每级攻速成长）
    """
    eid = int(ename) if str(ename).isdigit() else 0
    if eid in HERO_SPECIAL_STATS and HERO_SPECIAL_STATS[eid].get("cname") == cname:
        return HERO_SPECIAL_STATS[eid]
    for v in HERO_SPECIAL_STATS.values():
        if v.get("cname") == cname:
            return v

    main_role = role_str.split("/")[0] if role_str else "战士"
    tmpl = ROLE_BASE_TEMPLATES.get(main_role, ROLE_BASE_TEMPLATES["战士"])

    res = {
        "cname": cname,
        "hp": tmpl["hp"],
        "atk": tmpl["atk"],
        "pdef": tmpl["pdef"],
        "mdef": tmpl["mdef"],
        "speed": tmpl["speed"],
        "aspeed": tmpl["aspeed"],
    }
    if tmpl.get("aspeed_base"):
        res["aspeed_base"] = tmpl["aspeed_base"]
    return res
